// Builds the two generated files the search pages are made from (the notes sections and the sheet topics live on the server,
// and the client build only sees client files, so the client keeps a generated copy):
//   client/src/seo/content.js      small: per notes section its id, title, minutes and search description. Used by the app too.
//   client/src/seo/contentBody.js  large: section overviews, topic names and sheet topics. Used only by the build (scripts/prerender.mjs).
// Run after changing a notes section or a sheet: npm run build:seo-content. test/seo-content.test.js fails when the copies are stale.
const fs = require('fs');
const path = require('path');
const { sectionStats } = require('../src/modules/notes/notesStats');

const SEO_DIR = path.join(__dirname, '..', '..', 'client', 'src', 'seo');
const SUBJECTS = ['os', 'dbms', 'cn', 'oops', 'hld'];
const SHEET_FILES = ['blind75', 'neetCodeSeed', 'striverSDESeed', 'striverA2ZSeed', 'loveBabbarSeed'];
const DESCRIPTION_MIN = 110;
const DESCRIPTION_MAX = 160;
const DESCRIPTION_TAIL = 'Notes, common mistakes, interview questions and a short quiz.';

// plain text: no Markdown marks, links keep their words
const plain = (text) => String(text).replace(/`/g, '').replace(/\*\*?([^*]+)\*\*?/g, '$1').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1').replace(/\s+/g, ' ').trim();
// the notes explain a term in brackets at first use; a search snippet reads better without those asides
const withoutAsides = (text) => text.replace(/\s*\([^)]*\)/g, '');

// A search description from the first paragraph: whole sentences up to 160 characters; a short one gets a fixed tail.
function describe(overview) {
  const text = withoutAsides(overview);
  let out = text;
  if (out.length > DESCRIPTION_MAX) {
    const cut = out.slice(0, DESCRIPTION_MAX);
    const end = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('? '));
    out = end >= DESCRIPTION_MIN ? cut.slice(0, end + 1) : cut.slice(0, cut.lastIndexOf(' ')).replace(/[,;:\s]+$/, '') + '…';
  }
  if (out.length < DESCRIPTION_MIN && out.length + 1 + DESCRIPTION_TAIL.length <= DESCRIPTION_MAX) out += ' ' + DESCRIPTION_TAIL;
  return out;
}

function build() {
  const sections = {};
  const body = { notes: {}, sheets: {} };
  for (const subject of SUBJECTS) {
    const list = require(path.join('..', 'src', 'modules', 'notes', 'content', subject)).sections;
    sections[subject] = list.map((s) => ({ id: s.id, title: s.title, readMinutes: sectionStats(s).readMinutes, description: describe(plain(s.overview[0])) }));
    body.notes[subject] = Object.fromEntries(list.map((s) => [s.id, { overview: s.overview.slice(0, 2).map(plain), topics: s.topics.map((t) => plain(t.name)) }]));
  }
  const config = require.resolve('../src/shared/config/seedConfig');
  require.cache[config] = { id: config, filename: config, loaded: true, exports: async () => {} }; // the seeds would connect to a database otherwise
  for (const file of SHEET_FILES) {
    const { slug, topics } = require(`../src/modules/sheets/seeds/sheetSeeds/${file}`).data;
    body.sheets[slug] = topics.map((t) => ({ title: plain(t.title || t.topic), problems: t.problems.length }));
  }
  return { sections, body };
}

const HEADER = '// Generated by server/scripts/build-seo-content.js (npm run build:seo-content in the server folder). Do not edit by hand.\n';
const render = (value) => `${HEADER}export default ${JSON.stringify(value, null, 1)};\n`;

if (require.main === module) {
  const { sections, body } = build();
  fs.writeFileSync(path.join(SEO_DIR, 'content.js'), render(sections));
  fs.writeFileSync(path.join(SEO_DIR, 'contentBody.js'), render(body));
  console.log('wrote client/src/seo/content.js and contentBody.js');
}

module.exports = { build, render, describe, SEO_DIR, DESCRIPTION_MIN, DESCRIPTION_MAX };
